/* ---- tslfib radix 4 bwd (as in radix4_zts_tlfi_bwd_avx512.c) ---- */
static __attribute__((always_inline)) inline void _ztstlfi4b_body(
    const double *zin, double *out_re, double *out_im,
    const double *tw_re, size_t Ls, size_t OLs, size_t count)
{
    for (size_t k = 0; k + 8 <= count; k += 8) {
        _mm_prefetch((const char *)&out_re[(size_t)0*OLs + k + 64], _MM_HINT_T0);
        _mm_prefetch((const char *)&out_im[(size_t)0*OLs + k + 64], _MM_HINT_T0);
        _mm_prefetch((const char *)&out_re[(size_t)1*OLs + k + 64], _MM_HINT_T0);
        _mm_prefetch((const char *)&out_im[(size_t)1*OLs + k + 64], _MM_HINT_T0);
        _mm_prefetch((const char *)&out_re[(size_t)2*OLs + k + 64], _MM_HINT_T0);
        _mm_prefetch((const char *)&out_im[(size_t)2*OLs + k + 64], _MM_HINT_T0);
        _mm_prefetch((const char *)&out_re[(size_t)3*OLs + k + 64], _MM_HINT_T0);
        _mm_prefetch((const char *)&out_im[(size_t)3*OLs + k + 64], _MM_HINT_T0);
        /* ZBlockSplit load edge */
        const __m512d lane_re_0 = _mm512_loadu_pd(&zin[2*(size_t)k]);
        const __m512d lane_im_0 = _mm512_loadu_pd(&zin[2*(size_t)k + 8]);
        const __m512d lane_re_1 = _mm512_loadu_pd(&zin[2*((size_t)1*Ls + k)]);
        const __m512d lane_im_1 = _mm512_loadu_pd(&zin[2*((size_t)1*Ls + k) + 8]);
        const __m512d lane_re_2 = _mm512_loadu_pd(&zin[2*((size_t)2*Ls + k)]);
        const __m512d lane_im_2 = _mm512_loadu_pd(&zin[2*((size_t)2*Ls + k) + 8]);
        const __m512d lane_re_3 = _mm512_loadu_pd(&zin[2*((size_t)3*Ls + k)]);
        const __m512d lane_im_3 = _mm512_loadu_pd(&zin[2*((size_t)3*Ls + k) + 8]);
        /* zturn-ts split-plane store edge */
        /* SU-scheduled body (pipeline) */
        const __m512d t0 = lane_re_3;
        const __m512d t1 = _mm512_loadu_pd(&tw_re[6*(size_t)k + 32]);
        const __m512d t2 = lane_im_3;
        const __m512d t3 = _mm512_loadu_pd(&tw_re[6*(size_t)k + 40]);
        const __m512d t4 = _mm512_fnmadd_pd(t2, t3, _mm512_mul_pd(t0, t1));
        const __m512d t5 = _mm512_fmadd_pd(t0, t3, _mm512_mul_pd(t2, t1));
        const __m512d t9 = lane_re_1;
        const __m512d t10 = _mm512_loadu_pd(&tw_re[6*(size_t)k + 0]);
        const __m512d t11 = lane_im_1;
        const __m512d t12 = _mm512_loadu_pd(&tw_re[6*(size_t)k + 8]);
        const __m512d t13 = _mm512_fnmadd_pd(t11, t12, _mm512_mul_pd(t9, t10));
        const __m512d t14 = _mm512_fmadd_pd(t9, t12, _mm512_mul_pd(t11, t10));
        const __m512d t16 = _mm512_sub_pd(t14, t5);
        const __m512d t18 = _mm512_sub_pd(t13, t4);
        const __m512d t35 = _mm512_add_pd(t5, t14);
        const __m512d t36 = _mm512_add_pd(t4, t13);
        const __m512d t20 = lane_re_2;
        const __m512d t21 = _mm512_loadu_pd(&tw_re[6*(size_t)k + 16]);
        const __m512d t22 = lane_im_2;
        const __m512d t23 = _mm512_loadu_pd(&tw_re[6*(size_t)k + 24]);
        const __m512d t24 = _mm512_fnmadd_pd(t22, t23, _mm512_mul_pd(t20, t21));
        const __m512d t25 = _mm512_fmadd_pd(t20, t23, _mm512_mul_pd(t22, t21));
        const __m512d t27 = lane_re_0;
        const __m512d t31 = _mm512_sub_pd(t27, t24);
        const __m512d t32 = _mm512_add_pd(t16, t31);
        const __m512d t43 = _mm512_sub_pd(t31, t16);
        const __m512d t39 = _mm512_add_pd(t24, t27);
        const __m512d t40 = _mm512_sub_pd(t39, t36);
        const __m512d t45 = _mm512_add_pd(t36, t39);
        const __m512d t28 = lane_im_0;
        const __m512d t29 = _mm512_sub_pd(t28, t25);
        const __m512d t34 = _mm512_sub_pd(t29, t18);
        _mm512_storeu_pd(&out_re[(size_t)3*OLs + k], t32);
        _mm512_storeu_pd(&out_im[(size_t)3*OLs + k], t34);
        const __m512d t44 = _mm512_add_pd(t18, t29);
        _mm512_storeu_pd(&out_re[(size_t)1*OLs + k], t43);
        _mm512_storeu_pd(&out_im[(size_t)1*OLs + k], t44);
        const __m512d t38 = _mm512_add_pd(t25, t28);
        const __m512d t42 = _mm512_sub_pd(t38, t35);
        _mm512_storeu_pd(&out_re[(size_t)2*OLs + k], t40);
        _mm512_storeu_pd(&out_im[(size_t)2*OLs + k], t42);
        const __m512d t46 = _mm512_add_pd(t35, t38);
        _mm512_storeu_pd(&out_re[(size_t)k], t45);
        _mm512_storeu_pd(&out_im[(size_t)k], t46);
    }
}

